(() => {
const data=window.RANKS_TEAM_YEARS,esc=escapeHtml;
if(!data)return;
const years=data.rankings.map(r=>r.year).sort((a,b)=>b-a);
let year=years[0],mode='top5',query='';
window.selectTeamRankingYear=value=>{if(years.includes(Number(value)))year=Number(value);};
function singleEmblem(team,src){const c=team.logoCrop;if(!c)return `<span class="team-emblem team-initials">${esc(team.name.split(/\s+/).map(n=>n[0]).join('').slice(0,3))}</span>`;return `<span class="team-emblem"><img alt="Logo ${esc(team.name)}" src="${esc(src)}" style="width:${100/c.w}%;height:${100/c.h}%;left:${-100*c.x/c.w}%;top:${-100*c.y/c.h}%"></span>`;}
function emblem(team,src){if(!/Temp Stormy.*(?:GC|Goblins Cheating)/i.test(team.name))return singleEmblem(team,src);const gcRanking=data.rankings.find(r=>r.year===2018),gc=gcRanking.teams.find(t=>/GC 2018|GOBLINS CHEATING/i.test(t.name));return `<span class="team-emblem-pair">${singleEmblem({...team,name:'Temp Stormy'},src)}${singleEmblem({...gc,name:'Goblins Cheating'},gcRanking.sourceImage)}</span>`;}
function player(label,country){
const flag=country?`<i class="team-country" aria-label="${({BR:'Brasil',LT:'Lituânia',DE:'Alemanha',ES:'Espanha',FR:'França',PL:'Polônia'})[country]||country}">${country}</i>`:'';
const nick=label.match(/“([^”]+)”/)?.[1]||label,norm=s=>normalizeText(s).replace(/0/g,'o').replace(/[^a-z0-9]/g,''),aliases={tabsen:'tabsenn',conjure:'c0njure',ryota:'ry0ta',...(window.HBSTV_PLAYER_INDEX?.aliases||{})};
const displayNick=aliases[norm(nick)]||nick,target=players.find(p=>norm(p.name)===norm(displayNick)),id=window.getRegisteredPlayerId?.(displayNick),clickable=target||id;
const attr=target?`data-player="${players.indexOf(target)}"`:id?`data-entity-player="${id}"`:'';
return `<${clickable?'button':'div'} class="team-player" ${attr}><span>${esc(displayNick.slice(0,2))}</span><b>${flag}${esc(window.HBSTV?.name(displayNick)||displayNick)}</b>${label!==nick?`<small>${esc(label.split('“')[0].trim())}</small>`:target?'<small>Hall of Fame ↗</small>':id?'<small>Ver perfil ↗</small>':''}</${clickable?'button':'div'}>`;
}
const isMajor=(t,title)=>({2018:['TSL Major Premiere 1'],2019:['GSE | Major Extreme Masters 2019'],2021:['SUVOH Major'],2023:['RANK S Major League']})[t.year]?.includes(title);
const titleLabel=title=>title.includes('|')?title.replace(/\s*\|\s*/g,' | '):title.replace(/^(RANK S|GSC|WHL|GZ|ESC|BSTV|GSE|PNL|LCB|SUVOH|TSL|MAWARE|ACE)\s+(.+)$/,'$1 | $2');
function card(t,source,rank,champion){const roster=t.roster||[],titles=t.titles||[];return `<details class="team-rank-card ${rank===1?'team-first':''}" ${rank===1?'open':''}><summary><span class="team-position">#${rank}</span>${emblem(t,source)}<span class="team-name"><b>${esc(t.name)}</b><small>${champion?'TIME DO ANO':rank===1?'LÍDER DO RANKING ANUAL':'RANKING ANUAL'} · ${year}</small></span><span class="team-expand" aria-hidden="true">+</span></summary><div class="team-rank-body">${t.note?`<p class="team-unlisted">${esc(t.note)}</p>`:''}${roster.length?`<div class="team-subheading"><h4>Elenco registrado</h4><span>${roster.length} JOGADORES</span></div><div class="team-roster">${roster.map((label,i)=>player(label,t.countries?.[i])).join('')}</div>`:'<p class="team-unlisted">A arte deste ranking não informa a escalação desta equipe.</p>'}${titles.length?`<div class="team-subheading"><h4>Conquistas da temporada</h4><span>${titles.length} TÍTULOS</span></div><ul class="team-season-titles">${titles.map(title=>`<li class="${isMajor(t,title)?'team-title-major':''}">${window.renderOrganizationEmblem?.(titleLabel(title))||'<span aria-hidden="true">♜</span>'}<b>${esc(titleLabel(title))}</b>${isMajor(t,title)?'<em>MAJOR</em>':''}</li>`).join('')}</ul>`:''}</div></details>`;}
function render(){const ranking=data.rankings.find(r=>r.year===year),champion=data.champions.find(r=>r.year===year);let teams=mode==='top1'?(champion?[{...champion,rank:1}]:[]):ranking.teams;const term=normalizeText(query+' '+document.querySelector('#search').value).trim();teams=teams.filter(t=>!term||normalizeText([t.name,...t.roster||[],...t.titles||[]].join(' ')).includes(term));document.querySelector('#team-ranking-results').innerHTML=teams.length?teams.map(t=>card(t,mode==='top1'?t.sourceImage:ranking.sourceImage,t.rank,mode==='top1')).join(''):`<div class="empty">${mode==='top1'&&!champion?'Não há uma ficha de Time do ano de 2017 no acervo. Consulte o Top 5 deste ano.':'Nenhuma equipe encontrada.'}</div>`;document.querySelector('#team-ranking-title').textContent=`${mode==='top1'?'Time do ano':'Top 5 equipes'} · ${year}`;document.querySelectorAll('[data-team-year]').forEach(b=>{b.classList.toggle('active',+b.dataset.teamYear===year);b.setAttribute('aria-pressed',String(+b.dataset.teamYear===year));});document.querySelectorAll('[data-team-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.teamMode===mode);b.setAttribute('aria-pressed',String(b.dataset.teamMode===mode));});}
window.renderTeamYearsScreen=slug=>{if(slug!=='top-1-teams-of-years')return false;document.querySelector('#archive-reader').innerHTML=`<div class="reader-toolbar"><a href="#acervo">← Todas as coleções</a><a href="https://ranksorg.godaddysites.com/top-1-teams-of-years" target="_blank" rel="noopener">Fonte original ↗</a></div><header class="team-years-header"><span class="eyebrow">AS EQUIPES QUE DEFINIRAM CADA ERA</span><h2>Equipes do ano<span>.</span></h2><p>O ranking. Os elencos. As conquistas.</p></header><div class="team-years-layout"><aside class="team-year-filter"><h3>Temporada</h3>${years.map(y=>`<button data-team-year="${y}">${y}</button>`).join('')}</aside><div class="team-years-main"><div class="team-mode-tabs" aria-label="Tipo de ranking"><button data-team-mode="top5">Top 5 Teams of the Year</button><button data-team-mode="top1">Top 1 · Time do ano</button></div><div class="team-ranking-toolbar"><h3 id="team-ranking-title"></h3><input id="team-ranking-search" type="search" aria-label="Buscar equipe ou jogador" placeholder="Equipe ou jogador…" value="${esc(query)}"></div><div id="team-ranking-results"></div><p class="team-ranking-note">Elencos e títulos registrados ao longo da temporada; não representam necessariamente cinco titulares simultâneos. Anos sem publicação no acervo não aparecem no filtro.</p></div></div>`;render();return true;};
document.addEventListener('click',e=>{const y=e.target.closest('[data-team-year]'),m=e.target.closest('[data-team-mode]');if(y){year=+y.dataset.teamYear;render();}if(m){mode=m.dataset.teamMode;render();}});
document.addEventListener('input',e=>{if(e.target.id==='team-ranking-search'){query=e.target.value;render();}});
})();
